<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\Api\V1\{AuthController,CatalogController,AccountController};
use App\Http\Middleware\MobileAccountActive;
Route::prefix('v1')->group(function(){
    Route::get('auth/config',[\App\Http\Controllers\Api\V1\GoogleAuthController::class,'configuration']);
    Route::post('auth/google/start',[\App\Http\Controllers\Api\V1\GoogleAuthController::class,'start'])->middleware('throttle:5,1');
    Route::post('auth/google/exchange',[\App\Http\Controllers\Api\V1\GoogleAuthController::class,'exchange'])->middleware('throttle:20,1');
    Route::post('guest/bookings/{type}/{slug}',[\App\Http\Controllers\Api\V1\GuestBookingController::class,'store'])->middleware('throttle:3,1,guest-booking');
    Route::middleware('throttle:20,1,guest-checkout')->group(function(){

        Route::get('guest/resume',[\App\Http\Controllers\Api\V1\GuestBookingController::class,'resume']);
        Route::get('guest/checkout/{id}',[\App\Http\Controllers\Api\V1\GuestBookingController::class,'checkout']);
        Route::post('guest/checkout/{id}/{action}',[\App\Http\Controllers\Api\V1\GuestBookingController::class,'checkout'])->where('action','process|gateway|proof');
    });
    Route::get('public/articles',[\App\Http\Controllers\Api\V1\PublicContentController::class,'articles']);
    Route::get('public/home',[\App\Http\Controllers\Api\V1\PublicContentController::class,'home']);
    Route::get('public/home/blocks',[\App\Http\Controllers\Api\V1\HomeBlocksController::class,'index']);
    Route::get('public/articles/{slug}',[\App\Http\Controllers\Api\V1\PublicContentController::class,'article']);
    Route::get('public/pages/{page}',[\App\Http\Controllers\Api\V1\PublicContentController::class,'page']);
    Route::get('public/documentations',[\App\Http\Controllers\Api\V1\PublicContentController::class,'documentations']);
    Route::get('catalog/types',[CatalogController::class,'types']);
    Route::get('catalog/{type}/filters',[CatalogController::class,'filters']);
    Route::get('catalog/{type}',[CatalogController::class,'index']);
    Route::get('catalog/{type}/{slug}',[CatalogController::class,'show']);
    Route::post('catalog/{type}/{slug}/quote',[\App\Http\Controllers\Api\V1\BookingQuoteController::class,'show'])->middleware('throttle:30,1');
    Route::get('catalog/{type}/{slug}/reviews',[CatalogController::class,'reviews']);
    Route::post('catalog/{type}/{slug}/reviews',[CatalogController::class,'review'])->middleware('throttle:3,1');
    Route::post('auth/login',[AuthController::class,'login'])->middleware('throttle:5,1');
    Route::post('auth/register',[AuthController::class,'register'])->middleware('throttle:5,1');
    Route::post('auth/register-partner',[\App\Http\Controllers\Api\V1\PartnerRegistrationController::class,'store'])->middleware('throttle:3,1');
    Route::post('auth/forgot-password',[AuthController::class,'forgot'])->middleware('throttle:3,1');
    Route::post('auth/reset-password',[AuthController::class,'reset'])->middleware('throttle:5,1');
    Route::get('auth/verify/{id}/{hash}',[AuthController::class,'verify'])->middleware([\App\Http\Middleware\MobileVerificationSignature::class,'throttle:10,1'])->name('mobile.verify');
    Route::middleware(['auth:sanctum',MobileAccountActive::class])->group(function(){
        Route::post('account/device',[\App\Http\Controllers\Api\V1\DeviceController::class,'save'])->middleware('throttle:20,1');
        Route::post('account/device/remove',[\App\Http\Controllers\Api\V1\DeviceController::class,'destroy']);
        Route::get('admin/reports/orders',[\App\Http\Controllers\Api\V1\ReportController::class,'orders']);
        Route::get('admin/settings',[\App\Http\Controllers\Api\V1\SiteSettingsController::class,'types']);
        Route::get('admin/settings/{module}',[\App\Http\Controllers\Api\V1\SiteSettingsController::class,'form']);
        Route::post('admin/settings/{module}',[\App\Http\Controllers\Api\V1\SiteSettingsController::class,'save']);
        Route::get('admin/workflows',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'types']);
        Route::get('admin/workflows/{module}',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'index']);
        Route::get('admin/workflows/{module}/{id}',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'show']);
        Route::get('admin/workflows/{module}/{id}/documents/{document}',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'document']);
        Route::get('admin/workflows/{module}/{id}/form/{action}',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'form']);
        Route::post('admin/workflows/{module}/{id}/action/{action}',[\App\Http\Controllers\Api\V1\AdminWorkflowController::class,'action']);
        Route::get('member/{module}',[\App\Http\Controllers\Api\V1\MemberServicesController::class,'index']);
        Route::get('member/{module}/form/{action}',[\App\Http\Controllers\Api\V1\MemberServicesController::class,'form']);
        Route::post('member/{module}/action/{action}',[\App\Http\Controllers\Api\V1\MemberServicesController::class,'action'])->middleware('throttle:10,1');
        Route::post('member/wallet/withdrawals/{id}/delete',[\App\Http\Controllers\Api\V1\MemberServicesController::class,'deleteWithdrawal']);
        Route::get('manage/content',[\App\Http\Controllers\Api\V1\ContentManagementController::class,'types']);
        Route::get('manage/content/{type}',[\App\Http\Controllers\Api\V1\ContentManagementController::class,'index']);
        Route::get('manage/content/{type}/form/{id?}',[\App\Http\Controllers\Api\V1\ContentManagementController::class,'form']);
        Route::post('manage/content/{type}/save/{id?}',[\App\Http\Controllers\Api\V1\ContentManagementController::class,'save']);
        Route::post('manage/content/{type}/{id}/delete',[\App\Http\Controllers\Api\V1\ContentManagementController::class,'destroy']);
        Route::get('manage/products',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'types']);
        Route::get('manage/products/{type}',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'index']);
        Route::get('manage/products/{type}/form/{id?}',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'form']);
        Route::post('manage/products/{type}/save/{id?}',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'save']);
        Route::post('manage/products/{type}/{id}/delete',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'destroy']);
        Route::post('manage/products/{type}/{id}/review/{action}',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'review']);
        Route::post('manage/products/{type}/{id}/photos/{photo}/delete',[\App\Http\Controllers\Api\V1\ProductManagementController::class,'photo']);
        Route::middleware(['role:user','verified'])->group(function(){
            Route::post('bookings/{type}/{slug}',[\App\Http\Controllers\Api\V1\BookingController::class,'store'])->middleware('throttle:10,1');
            Route::get('checkout/{id}',[\App\Http\Controllers\Api\V1\CheckoutController::class,'show']);
            Route::post('checkout/{id}',[\App\Http\Controllers\Api\V1\CheckoutController::class,'process']);
            Route::post('checkout/{id}/gateway',[\App\Http\Controllers\Api\V1\CheckoutController::class,'gateway'])->middleware('throttle:5,1');
            Route::post('checkout/{id}/proof',[\App\Http\Controllers\Api\V1\CheckoutController::class,'proof'])->middleware('throttle:5,1');
        });
        Route::get('auth/me',[AuthController::class,'me']);
        Route::get('account/dashboard',[AccountController::class,'dashboard']);
        Route::get('account/orders',[AccountController::class,'orders']);
        Route::get('account/orders/{id}',[AccountController::class,'order']);
        Route::get('account/orders/{id}/invoice',[AccountController::class,'invoice']);
        Route::get('account/orders/{id}/contact',[AccountController::class,'contact']);
        Route::post('account/orders/{id}/delete',[AccountController::class,'deletePartnerOrder']);
        Route::post('account/profile',[AccountController::class,'profile']);
        Route::post('account/password',[AccountController::class,'password'])->middleware('throttle:5,1');
        Route::get('account/notifications',[AccountController::class,'notifications']);
        Route::post('account/notifications/{id}/read',[AccountController::class,'readNotification']);
        Route::post('auth/logout',[AuthController::class,'logout']);
        Route::post('auth/verification-notification',[AuthController::class,'resend'])->middleware('throttle:3,1');
    });
});
